    ["恐怖灵异", 7],
    ["言情小说", 8],
    ["动漫同人", 9],
    ["其他类型", 10]
  ];

  const ranks = [
    ["人气", "weekvisit"],
    ["推荐", "allvote"],
    ["新书", "newhot"]
  ];

  const stats = [
    ["连载", 0],
    ["全本", 1]
  ];


  let disc = [];

  cats.forEach(c => {
    disc.push({
      title: c[0],
      url: "",
      style: {layout_flexBasisPercent: 1, layout_flexGrow: 1}
    });
    if (c[1] === "full" || c[1] === "class") {
      subs.forEach(s => {
        disc.push({
          title: s[0],
          url: `/novels/${c[1]}/${s[1]}_{{page}}.html`,
          style: {layout_flexBasisPercent: 0.24, layout_flexGrow: 0.32}
        });
      });
      if (c[1] === "class") {
        subs.forEach(sb => {
          disc.push({
            title: `${sb[0]}排行榜`,
            url: "",
            style: {layout_flexBasisPercent: 1, layout_flexGrow: 1}
          });
          stats.forEach(st => {
            ranks.forEach(r => {
              disc.push({
                title: `${r[0]}-${st[0]}`,
                url: `/novels/${r[1]}_${sb[1]}_${st[1]}_{{page}}.html`,
                style: {layout_flexGrow: 1}
              });
            });
          });
        });
      }
    } 
  });

  disc.push({
            title: `热门标签`,
            url: "",
            style: {layout_flexBasisPercent: 1, layout_flexGrow: 1}
          });
 let url = baseUrl.replaceAll(/[^\w]+$/gi, '');
  let tagHtml = java.ajax(`${url}/newtags`);
  if (String(tagHtml).includes('cf_chl')) {
    let res =java.startBrowserAwait(`${url}/newtags`, "验证", false);
    tagHtml = res.body();
  }
  let doc = org.jsoup.Jsoup.parse(tagHtml);
  let tags = doc.select(".tag ul a");
  Array.from(tags).forEach(a => {
    let txt = a.ownText().trim();
    let t = java.t2s(txt);
    disc.push({
      title: t,
      url: source.key + "/newtag/" + encodeURI(txt) + "/{{page}}",
      style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 0.25
      }
    });
  });

  disc.push({
    title: "最近更新",
    url: "/last",
    style: {layout_flexBasisPercent: 1, layout_flexGrow: 1}
  });

  return JSON.stringify(disc);
}
shux();

loginCheckJs:
var resultUrl = result.url();
var resultCode = result.code();
var resultBoDy = result.body();
if (/_cf_|ge_ua|verify.php/ig.test(resultBoDy) && resultCode >= 403) {
    if (key) {
        url = baseUrl + java.ruleUrl;
    }
    cookie.removeCookie(baseUrl)
    result = java.startBrowserAwait(resultUrl, 
        "验证", false); 
    if(key){
        src = result.body();
        url = org.jsoup.Jsoup.parse(src).select('meta[property="og:url"]').attr('content');
        if(url != "" ){
            result = Packages.io.legado.app.help.http.StrResponse(url, src);
        }
    }
}
result;

